<script setup>
import { onMounted, ref } from 'vue'
const props=defineProps({api:{type:Function,required:true}})
const tab=ref('status'),status=ref(null),queue=ref(null),workload=ref([]),masters=ref([]),failed=ref([]),audit=ref([]),failedTotal=ref(0),auditTotal=ref(0),page=ref(1),filter=ref({action:'',admin_id:'',keyword:''}),loading=ref(false),error=ref(''),mastersError=ref('')
async function load(){loading.value=true;error.value='';mastersError.value='';try{const results=await Promise.allSettled([props.api('system/getSystemStatus'),props.api('system/getQueueStats'),props.api('system/getQueueWorkload'),props.api('system/getQueueMasters')]);status.value=results[0].status==='fulfilled'?results[0].value:null;queue.value=results[1].status==='fulfilled'?results[1].value:null;workload.value=results[2].status==='fulfilled'?(results[2].value||[]):[];masters.value=results[3].status==='fulfilled'?(results[3].value?.data||results[3].value||[]):[];error.value=results.slice(0,3).filter(r=>r.status==='rejected').map(r=>r.reason?.message).join('；');if(results[3].status==='rejected')mastersError.value=results[3].reason?.status===403?'HTTP 403：此路由调用 Laravel Horizon 内置控制器，Horizon 授权门拒绝了 Xboard 管理员请求。修复需在 Xboard 后端让该受保护路由通过管理员授权，或改由现有 Admin 中间件下的 SystemController 读取 MasterSupervisorRepository；不要把 Horizon 面板公开。':results[3].reason?.message||'读取 Horizon 主进程失败。';if(tab.value==='failed')await loadFailed();if(tab.value==='audit')await loadAudit()}finally{loading.value=false}}
async function loadFailed(){try{const r=await props.api(`system/getHorizonFailedJobs?current=${page.value}&page_size=20`);failed.value=r.data||[];failedTotal.value=r.total||0}catch(e){error.value=e.message}}
async function loadAudit(){try{const q=new URLSearchParams({current:String(page.value),page_size:'20'});for(const [k,v] of Object.entries(filter.value))if(v)q.set(k,v);const r=await props.api(`system/getAuditLog?${q}`);audit.value=r.data||[];auditTotal.value=r.total||0}catch(e){error.value=e.message}}
async function changeTab(name){tab.value=name;page.value=1;if(name==='failed')await loadFailed();if(name==='audit')await loadAudit()}
function json(v){return JSON.stringify(v,null,2)}
onMounted(load)
</script>
<template><section class="system-view"><div class="page-title-row"><div><p class="eyebrow">SYSTEM / HEALTH</p><h1>系统状态<span class="title-period">.</span></h1><p class="page-subtitle">计划任务、Horizon 队列、失败任务与管理员审计日志。</p></div><button class="refresh-button" @click="load">↻ <span>刷新状态</span></button></div><div class="system-tabs"><button v-for="item in [['status','运行状态'],['failed','失败任务'],['audit','审计日志']]" :key="item[0]" :class="{selected:tab===item[0]}" @click="changeTab(item[0])">{{item[1]}}</button></div><p v-if="error" class="notice">{{error}}</p><template v-if="tab==='status'"><div class="gift-stat-grid"><article class="metric-card"><div class="metric-top"><span>计划任务</span><span class="metric-icon teal">◷</span></div><div class="metric-value">{{status?.schedule?'运行中':'未检测到'}}</div><div class="metric-foot"><span class="metric-caption">最近执行 {{status?.schedule_last_runtime||'—'}}</span></div></article><article class="metric-card"><div class="metric-top"><span>Horizon</span><span class="metric-icon blue">⇄</span></div><div class="metric-value">{{queue?.status?'运行中':'已暂停'}}</div><div class="metric-foot"><span class="metric-caption">进程 {{queue?.processes||0}} · 暂停主进程 {{queue?.pausedMasters||0}}</span></div></article><article class="metric-card"><div class="metric-top"><span>队列任务</span><span class="metric-icon amber">▤</span></div><div class="metric-value">{{queue?.jobsPerMinute||0}}<small> / 分钟</small></div><div class="metric-foot"><span class="metric-caption">近期失败 {{queue?.failedJobs||0}} · 最近任务 {{queue?.recentJobs||0}}</span></div></article></div><div class="system-grid"><article class="data-panel"><div class="panel-heading"><div><p class="eyebrow">QUEUE / WORKLOAD</p><h2>队列负载</h2></div></div><pre class="response-json">{{json(workload)}}</pre></article><article class="data-panel"><div class="panel-heading"><div><p class="eyebrow">HORIZON / MASTERS</p><h2>主进程</h2></div></div><p v-if="mastersError" class="notice">{{mastersError}}</p><pre v-else class="response-json">{{json(masters)}}</pre></article></div></template><article v-else-if="tab==='failed'" class="data-panel"><div class="panel-heading"><div><p class="eyebrow">QUEUE / FAILED JOBS</p><h2>失败任务 · {{failedTotal}}</h2></div></div><pre class="response-json">{{json(failed)}}</pre><div class="table-pagination"><span>第 {{page}} 页</span><div><button :disabled="page<=1" @click="page--;loadFailed()">← 上一页</button><button :disabled="page*20>=failedTotal" @click="page++;loadFailed()">下一页 →</button></div></div></article><article v-else class="data-panel"><div class="panel-heading"><div><p class="eyebrow">ADMIN / AUDIT</p><h2>操作审计 · {{auditTotal}}</h2></div></div><form class="system-filters" @submit.prevent="page=1;loadAudit()"><input v-model="filter.action" placeholder="操作类型"><input v-model="filter.admin_id" placeholder="管理员 ID"><input v-model="filter.keyword" placeholder="URI 或请求内容"><button>筛选</button></form><div class="users-table-wrap"><table class="report-table"><thead><tr><th>ID</th><th>管理员</th><th>操作</th><th>请求</th><th>时间</th></tr></thead><tbody><tr v-for="row in audit" :key="row.id"><td>{{row.id}}</td><td>{{row.admin?.email||row.admin_id||'—'}}</td><td>{{row.action}}</td><td><code>{{row.method}} {{row.uri}}</code><pre>{{json(row.request_data)}}</pre></td><td>{{row.created_at||'—'}}</td></tr></tbody></table><div v-if="!audit.length&&!loading" class="table-state">没有匹配的审计记录。</div></div><div class="table-pagination"><span>第 {{page}} 页</span><div><button :disabled="page<=1" @click="page--;loadAudit()">← 上一页</button><button :disabled="page*20>=auditTotal" @click="page++;loadAudit()">下一页 →</button></div></div></article></section></template>
